ALTER POLICY "chat_conversations_select" ON "chat_conversations" TO authenticated USING (tenant_id = app.tenant_id() and ((kind = 'support' and app.tenant_role() in ('admin_tenant', 'support_tenant')) or created_by_user_id = app.user_id() or exists (select 1 from public.chat_participants p where p.conversation_id = chat_conversations.id and p.tenant_id = app.tenant_id() and p.user_id = app.user_id())) and (direct_low_user_id is null or (select app.direct_pair_readable(direct_low_user_id, direct_high_user_id))));--> statement-breakpoint
ALTER POLICY "chat_conversations_insert" ON "chat_conversations" TO authenticated WITH CHECK (tenant_id = app.tenant_id() and created_by_user_id = app.user_id() and last_seq = 0 and last_staff_seq = 0 and staff_last_read_seq = 0 and last_message_side is null and last_message_at is null and case_number is null and owner_user_id is null and resolved_at is null and closed_at is null and kind = 'support' and (priority is null or priority = 'normal') and (state is null or state = 'open'));